// Export — the test side of #63 (P5.10). A mapping, not a serialiser, for
// the same reason `export/bank.ts` is one: `toTestDocument`
// (packages/db/src/repo/test-document.ts) already turns a stored body plus
// its `IdRefs` into a whole `pariksha/test@1` document, so this file's only
// jobs are fetching what that mapping needs and deciding which version.
//
// **The `tst_` id, the short code and the QR code are omitted** —
// docs/test-format.md § Identity says so outright ("generated by Pariksha
// and are not part of the file, so an exported test can be imported
// anywhere without colliding"), and `toTestDocument` never had them in the
// first place: they live on the `test` row, not in `settings_json`.
//
// **A bank's *name* is what plays the part of the file path.** The format
// calls `banks` "bank files … relative to the test file" and a `pool`
// source names one of them; inside a workspace there is no file, so the
// bank's name is the only stable, human-chosen string either end can
// agree on, and import resolves `source.bank` back by the same name.

import { validateTest, type ImportIssue, type Test } from "@pariksha/core";
import {
  getDraftVersion,
  getPublishedVersion,
  getTest,
  listBanks,
  toTestDocument,
  workspaceQuestions,
  type IdRefs,
  type TestVersionRow,
  type WorkspaceQuestion,
} from "@pariksha/db";
import type { AppDeps } from "../app.js";
import { ApiError } from "../errors.js";
import { validateTestDocumentStructure } from "../import/schema.js";
import testSchema from "../../../../schemas/test-1.json" with { type: "json" };

/** `schemas/test-1.json`'s own `$id` — the same string every export
 * carries, regardless of what the imported document's own `$schema` said.
 * Nothing stores a test's `$schema`: there is no column for it, exactly as
 * there is none for a bank's. */
const TEST_SCHEMA_ID = (testSchema as { $id: string }).$id;

/** Both directions of both translations, built from one `workspaceQuestions`
 * and one `listBanks`. A `ref_id` is unique per bank, not per workspace
 * (`columns.ts`, `question.uniques: [["bank_id","ref_id"]]`), so the
 * ref→row direction keeps the first match and import reports the ambiguity
 * rather than this silently picking a side. */
export function idRefsOf(questions: readonly WorkspaceQuestion[], banks: readonly { id: string; name: string }[]): IdRefs {
  const questionIdByRef = new Map<string, string>();
  const refByQuestionId = new Map<string, string>();
  for (const q of questions) {
    if (!questionIdByRef.has(q.refId)) questionIdByRef.set(q.refId, q.id);
    refByQuestionId.set(q.id, q.refId);
  }
  const bankIdByFile = new Map<string, string>();
  const fileByBankId = new Map<string, string>();
  for (const bank of banks) {
    if (!bankIdByFile.has(bank.name)) bankIdByFile.set(bank.name, bank.id);
    fileByBankId.set(bank.id, bank.name);
  }
  return { questionIdByRef, refByQuestionId, bankIdByFile, fileByBankId };
}

/** Which banks the document should declare: every bank a `pool` section
 * names outright, plus the bank each question a `fixed`/`sets` source names
 * actually lives in. In the order they are first mentioned, so the list is
 * stable across exports rather than hash-ordered. */
function banksNamed(
  version: TestVersionRow,
  questions: readonly WorkspaceQuestion[],
  refs: IdRefs,
): string[] {
  const bankOfQuestion = new Map(questions.map((q) => [q.id, q.bankId]));
  const names: string[] = [];
  const add = (bankId: string | undefined): void => {
    const name = bankId === undefined ? undefined : refs.fileByBankId.get(bankId);
    if (name !== undefined && !names.includes(name)) names.push(name);
  };

  for (const section of version.body.sections) {
    const source = section.source;
    if (source.kind === "pool") add(source.bank);
    else if (source.kind === "fixed") for (const id of source.questions) add(bankOfQuestion.get(id));
    else for (const set of source.sets) for (const id of set.questions) add(bankOfQuestion.get(id));
  }
  return names;
}

/**
 * The version to export: `?version=N` names a frozen one, the default is
 * `current_version`, and a test with nothing published yet exports its
 * draft head instead, so a complete-but-unpublished test is exportable.
 * (A test too unfinished to import is still refused — see
 * `testExportIssues`.)
 */
async function versionToExport(
  deps: AppDeps,
  workspaceId: string,
  testId: string,
  version: number | undefined,
): Promise<TestVersionRow> {
  const published = await getPublishedVersion(deps.db, workspaceId, testId, version);
  if (published) return published;
  if (version !== undefined) {
    throw new ApiError(404, "not_found", "No such resource.");
  }
  const draft = await getDraftVersion(deps.db, workspaceId, testId);
  if (!draft) throw new ApiError(404, "not_found", "No such resource.");
  return draft;
}

export async function exportTest(
  deps: AppDeps,
  workspaceId: string,
  testId: string,
  version?: number,
): Promise<Test> {
  const test = await getTest(deps.db, workspaceId, testId);
  if (!test) throw new ApiError(404, "not_found", "No such resource.");

  const row = await versionToExport(deps, workspaceId, testId, version);
  const questions = await workspaceQuestions(deps.db, workspaceId);
  const banks = await listBanks(deps.db, workspaceId);
  const refs = idRefsOf(questions, banks);

  const named = banksNamed(row, questions, refs);
  const doc = toTestDocument(test, row.body, refs);

  // `banks` is derived from what the sections actually draw from rather
  // than carried through `settings`, so an export cannot declare a bank the
  // test stopped using — and is omitted entirely when nothing is named,
  // because the format calls it optional and `"banks": []` would be a
  // claim rather than an omission.
  const { banks: _stored, ...rest } = doc;
  const exported: Test = { "$schema": TEST_SCHEMA_ID, ...rest, ...(named.length > 0 && { banks: named }) };

  // `export/bank.ts`'s own rule, applied to the other document: never hand
  // an author a file this system's own `/import` would reject. Checked
  // here rather than in the route so the `workspaceQuestions` read above is
  // the only one — a second call in the caller would cost a subrequest to
  // re-fetch what this function already holds.
  const issues = testExportIssues(exported, questions.map((q) => q.document));
  if (issues.length > 0) {
    throw new ApiError(422, "not_exportable", "This test is not complete enough to export.", { issues });
  }
  return exported;
}

/**
 * Every issue `doc` would be refused for on its own way back in through
 * `/tests/import` — structural (`schemas/test-1.json` unstripped, so the
 * root `required` and every emptiness floor the save gate drops) and
 * cross-field (`validateTest`).
 *
 * The property this buys is `export/bank.ts`'s own, applied to the other
 * document: **this system never hands an author a file it will not take
 * back.** It is also why export is stricter than publish — publish only
 * *warns* about a short pool (T-11) while import refuses the file
 * (docs/test-format.md § "Rules checked on import": "Import is stricter").
 * A test too unfinished to import is too unfinished to export.
 *
 * `doc` is round-tripped through `JSON.stringify`/`parse` first, for the
 * reason `exportIssues` states: the in-memory shape can carry explicit
 * `undefined` properties that `c.json()` drops and `@cfworker/json-schema`
 * throws on. Validating the bytes the response will actually carry is also
 * the more honest check.
 */
export function testExportIssues(doc: Test, questions: readonly { id: string }[]): ImportIssue[] {
  const json = JSON.parse(JSON.stringify(doc)) as unknown;
  const structural = validateTestDocumentStructure(json);
  const crossField = validateTest(json, questions as never);
  return [...structural, ...(crossField.ok ? [] : crossField.issues)];
}
